package com.campusconnect.assignment; import com.campusconnect.user.User; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="submissions",uniqueConstraints=@UniqueConstraint(columnNames={"assignment_id","student_id"})) public class Submission { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Assignment assignment; @ManyToOne(optional=false) @JoinColumn(name="student_id") private User student; @Column(nullable=false,length=10000) private String content; @Column(nullable=false,updatable=false) private Instant submittedAt=Instant.now(); private Double grade; @Column(length=2000) private String feedback; protected Submission(){} public Submission(Assignment a,User u,String c){assignment=a;student=u;content=c;} public Long getId(){return id;} public Assignment getAssignment(){return assignment;} public User getStudent(){return student;} public String getContent(){return content;} public Instant getSubmittedAt(){return submittedAt;} public Double getGrade(){return grade;} public String getFeedback(){return feedback;} public void grade(Double g,String f){grade=g;feedback=f;} public void updateContent(String c){if(grade!=null)throw new IllegalArgumentException("A graded submission cannot be changed");content=c;submittedAt=Instant.now();} }
